example.code:
var options = new TelemetryOptions 
{ 
    CustomerConnectionString = "base64-encoded-connection-string"
};
var result = Telemetry.EnableCustomerInsights(options);
if (result.IsValid)
{
    Console.WriteLine("Customer insights enabled!");
}
else
{
    Console.WriteLine($"Error: {result.Message}");
}

member.summary:
Manages customer telemetry configuration globally for the application.

Supports multiple customer telemetry platforms:
- Azure Application Insights (via connection string)
- AWS CloudWatch Logs (via AWS credentials)

This is a static manager that stores customer connection details once during application
startup, and makes them available throughout the application lifetime for automatic
dual-logging of telemetry data.

USAGE:
------
  // Setup Azure (optional)
  var azureResult = CustomerInsightsManager.SetupCustomerInsights(connectionString);
  
  // Setup AWS CloudWatch (optional)
  var awsResult = CustomerInsightsManager.SetupAwsCloudWatch(awsConnectionString);

member.example:
In Program.cs:
  var connectionString = Environment.GetEnvironmentVariable("CUSTOMER_INSIGHTS_CONNECTION");
  var result = CustomerInsightsManager.SetupCustomerInsights(connectionString);
  
  if (result.IsValid)
  {
      Console.WriteLine("✓ Customer insights configured!");
  }
  
  // Now use telemetry normally - it will automatically log to both endpoints
  Telemetry.Configure(options);
  Telemetry.TrackFeature("MyFeature", ComponentName.Grid);

In Program.cs:
  var connectionString = Environment.GetEnvironmentVariable("AWS_CLOUDWATCH_CONNECTION");
  var result = CustomerInsightsManager.SetupAwsCloudWatch(connectionString);
  
  if (result.IsValid)
  {
      Console.WriteLine("✓ AWS CloudWatch configured!");
  }
  
  // Now use telemetry normally - it will automatically log to both endpoints
  Telemetry.Configure(options);
  Telemetry.TrackFeature("MyFeature", ComponentName.Grid);

member.summary:
Sets up customer telemetry for any supported platform using string-based platform name.

Provides a unified entry point for configuring customer telemetry regardless of the
underlying platform. Supports configuring multiple platforms simultaneously.

USAGE EXAMPLES:
──────────────
// Configure Azure
var result = CustomerInsightsManager.SetupTelemetry("Azure", azureConnectionString);

// Configure AWS CloudWatch
var result = CustomerInsightsManager.SetupTelemetry("AwsCloudWatch", awsConnectionString);

// Configure both simultaneously (for redundancy or migration)
CustomerInsightsManager.SetupTelemetry("Azure", azureConnectionString);
CustomerInsightsManager.SetupTelemetry("AwsCloudWatch", awsConnectionString);

After setup, all Telemetry.TrackFeature() calls automatically log to all
configured platforms.

member.example:
In Program.cs:
  // Load from environment variables
  var azureConn = Environment.GetEnvironmentVariable("TELEMETRY_AZURE");
  var awsConn = Environment.GetEnvironmentVariable("TELEMETRY_AWS");
  
  // Configure both platforms
  if (!string.IsNullOrEmpty(azureConn))
  {
      var azureResult = CustomerInsightsManager.SetupTelemetry("Azure", azureConn);
      if (azureResult.IsValid)
          Console.WriteLine("✓ Azure telemetry configured");
  }
  
  if (!string.IsNullOrEmpty(awsConn))
  {
      var awsResult = CustomerInsightsManager.SetupTelemetry("AwsCloudWatch", awsConn);
      if (awsResult.IsValid)
          Console.WriteLine("✓ AWS telemetry configured");
  }
  
  // Now use telemetry - it works with all configured platforms!
  Telemetry.Configure(options);
  Telemetry.TrackFeature("AppStarted", ComponentName.General);

member.summary:
Parses AWS CloudWatch connection strings to extract credentials and configuration.

This class mirrors the functionality of AzureConnectionStringParser but for AWS.
It handles Base64-encoded connection strings in the format:
AccessKeyId=AKIA...;SecretAccessKey=wJal...;Region=us-east-1;LogGroupName=/my-app/telemetry;LogStreamName=stream1

USAGE:
------
var parser = new AwsConnectionStringParser();
if (parser.Parse(base64EncodedConnectionString))
{
    string accessKeyId = parser.AccessKeyId;
    string secretAccessKey = parser.SecretAccessKey;
    string region = parser.Region;
    string logGroupName = parser.LogGroupName;
    string logStreamName = parser.LogStreamName;  // May be empty if not provided
}
